import{_ as e,o as i,c as s,a3 as t}from"./chunks/framework.D3kUw6rp.js";const l="/assets/1.DLjZep0P.png",m=JSON.parse('{"title":"文档地址中转","description":"","frontmatter":{},"headers":[],"relativePath":"work/cocos/short-url/index.md","filePath":"work/cocos/short-url/index.md"}'),r={name:"work/cocos/short-url/index.md"};function o(n,a,c,p,h,d){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="文档地址中转" tabindex="-1">文档地址中转 <a class="header-anchor" href="#文档地址中转" aria-label="Permalink to &quot;文档地址中转&quot;">​</a></h1><h2 id="我们遇到的问题" tabindex="-1">我们遇到的问题 <a class="header-anchor" href="#我们遇到的问题" aria-label="Permalink to &quot;我们遇到的问题&quot;">​</a></h2><p>在编辑器的各个面板里经常有跳转文档的按钮方便用户进行查看。但是随着时间的推移，有些文档地址做了修改，原先写死在代码里的地址就失效了。靠人为的维护这份数据是不可控的。而且发现问题之后也不能及时更新修正，需要等下一次发版。</p><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>我们需要一套地址中转服务用来处理地址的重定向。它的主要功能是解析编辑器向他发起的地址参数，通过特定的规则，将这些参数组装成目标地址，进行重定向。 如果之前的地址失效了，它还可以维护一份映射关系，把旧地址重定向到新地址去。</p><p>优点如下：</p><ul><li>在代码里不要写完整的链接地址，只需要声明关键参数即可</li><li>不管后期的文档地址如何变化，只要必要的参数不变，则只要更新中转服务的组装规则即可</li><li>如果有旧地址失效了，需要重定向到新地址，可以在线配置映射关系，及时生效。</li></ul><p><img src="'+l+'" alt="image"></p><p>如图示中流程：</p><ul><li>引擎的代码里只要加个 @doc 修饰器并声明必要的参数即可。</li><li>编辑器会加上一些公共参数如当前的版本信息等</li><li>中转服务根据得到的参数，按约定好的规则进行组装，得到文档的真实地址</li><li>进入文档页面</li></ul><p>如果新的文档系统，就是改了某个文档地址，可以考虑修改规则或者添加一份映射关系，将旧地址和新地址关联起来，由于都是在服务器配置，所以是及时生效的。避免用户看到 404 的情况。</p><h2 id="疑问" tabindex="-1">疑问 <a class="header-anchor" href="#疑问" aria-label="Permalink to &quot;疑问&quot;">​</a></h2><p>现在我们如何知道哪些参数是引擎代码里必填的呢？ 比如 <a href="https://docs.cocos.com/creator/api/zh/class/BaseRenderData" target="_blank" rel="noreferrer">https://docs.cocos.com/creator/api/zh/class/BaseRenderData</a> 这个地址:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">doc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({type: class, name: baseRenderData})</span></span></code></pre></div><p>引擎里是传这样吗？希望 @godIsAProgrammer 或者引擎同学帮忙指点一下。</p><h2 id="实现步骤" tabindex="-1">实现步骤 <a class="header-anchor" href="#实现步骤" aria-label="Permalink to &quot;实现步骤&quot;">​</a></h2><ul><li>引擎增加文档地址参数的修饰器</li><li>编辑器增加一层组装，将一些公共配置如 version、language 等和修饰器里的参数一起拼接地址</li><li>维护一套中转服务用于重定向处理，需要一套明确的解析规则和维护一套废弃地址的映射表</li><li>文档系统（尽量设计的 url 有规律可循，要不然中转系统无法沉淀出规则）</li></ul>',17)])])}const _=e(r,[["render",o]]);export{m as __pageData,_ as default};
